}

// Publish ke MQTT
var mqttMsg = {payload: body, topic: 'iot/kontrol'};

msg.statusCode = 200;
msg.payload = {
    status: 'success',
    message: 'Perintah terkirim',
    sent: body
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return [msg, mqttMsg];

