var body = msg.payload || {};
var batas = Number(body.suhu_max);

if (body.suhu_max === undefined || body.suhu_max === '' || isNaN(batas)) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'suhu_max wajib diisi berupa angka'};
} else {
    flow.set('threshold', batas);
    msg.statusCode = 200;
    msg.payload = {status: 'success', message: 'Threshold diperbarui', suhu_max: batas};
}
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

// === CEK API KEY ===
var kunciBenar = flow.get('apiKey');
var kunciKirim = msg.req.headers['x-api-key'];
if (!kunciKirim || kunciKirim !== kunciBenar) {
    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid atau tidak ada'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return msg;
}
// === END CEK API KEY ===

var batas = flow.get('threshold');
if (batas === undefined || batas === null) { batas = 30; }
msg.payload = {
    status: 'success',
    suhu_max: batas,
    alert: flow.get('alert') || false
};
msg.statusCode = 200;
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

var batas = flow.get('threshold');
if (batas === undefined || batas === null) {
    batas = 30;
    flow.set('threshold', batas);
}

var suhu = msg.payload.suhu;
var melewati = suhu > batas;
flow.set('alert', melewati);

if (!melewati) { return null; }

msg.topic = 'iot/notifikasi';
msg.payload = {
    status: 'warning',
    pesan: 'Suhu ' + suhu + ' C melewati batas ' + batas + ' C',
    suhu: suhu,
    batas: batas,
    waktu: new Date().toISOString()
};
return msg;

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;

flow.set('apiKey', 'iot-kampus-2026');
node.status({fill: 'green', shape: 'dot', text: 'API key tersimpan'});
return null;

var data = msg.payload;

var batas = flow.get('threshold');
if (batas === undefined || batas === null) { batas = 30; }

msg.payload = {
    type: 'sensor',
    data: data,
    threshold: batas,
    alert: data.suhu > batas
};
return msg;

msg.topic = 'CREATE TABLE IF NOT EXISTS history (id INTEGER PRIMARY KEY AUTOINCREMENT, suhu REAL, kelembaban REAL, timestamp TEXT, received TEXT)';
msg.payload = [];
return msg;

var d = msg.payload;
msg.topic = 'INSERT INTO history (suhu, kelembaban, timestamp, received) VALUES (?, ?, ?, ?)';
msg.payload = [d.suhu, d.kelembaban, d.timestamp, d.received];
return msg;

