    msg.statusCode = 401;
    msg.payload = {status: 'error', message: 'API key tidak valid atau tidak ada'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null];
}
// === END CEK API KEY ===

// Ambil 50 data terakhir, urut dari terlama ke terbaru
msg.topic = 'SELECT suhu, kelembaban, timestamp, received FROM (SELECT * FROM history ORDER BY id DESC LIMIT 50) ORDER BY id ASC';
msg.payload = [];
return [null, msg];

var rows = Array.isArray(msg.payload) ? msg.payload : [];
msg.payload = {status: 'success', count: rows.length, data: rows};
msg.statusCode = 200;
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;
